'use strict';
const E=FluxEngine;
const productPages=[['perpetuals','Perpetuals'],['lending','Lending'],['liquidity','Market making']];
for(const [id,label] of productPages){const b=document.createElement('button');b.className='nav';b.dataset.page=id;b.textContent=label;b.onclick=()=>{navigate(id);refreshProducts()};$('nav').insertBefore(b,$('[data-page="markets"]'));}
const field=(label,id,value,unit,min='0.01')=>`<label>${label}<div class="input-wrap"><input id="${id}" type="number" min="${min}" step="any" value="${value}" required><span>${unit}</span></div></label>`;
const shells=document.createElement('div');shells.innerHTML=`
<section id="perpetuals-page" hidden>
 <div class="product-heading"><div><span class="eyebrow">01 / PERPETUAL FUTURES</span><h2>Take a view. Keep your position.</h2><p>Long or short ETH with isolated margin and funding recalculated every simulated block.</p></div><span class="demo-pill">SIMULATION · NO REAL FUNDS</span></div>
 <div class="product-grid"><div class="product-main"><div class="metric-row" id="perp-metrics"></div>
 <div class="product-card scenario"><div class="panel-title">Market scenarios <span id="block-label"></span></div><p>Advance one block and move the index. Funding transfers and liquidation checks run on every step.</p><div class="scenario-buttons"><button data-move="-5">−5% stress</button><button data-move="-1">−1%</button><button data-move="0">Next block →</button><button data-move="1">+1%</button><button data-move="5">+5% rally</button></div><p class="fineprint">Synthetic index and mark prices. Positive funding: longs pay, shorts receive. Negative funding reverses the transfer. Demo funding is capped at ±0.01% per block.</p></div>
 <div class="product-card"><div class="panel-title">Open positions <span>Isolated margin</span></div><div class="table-scroll" id="positions"></div></div><div class="product-card"><div class="panel-title">Closed positions</div><div class="table-scroll" id="closed-positions"></div></div></div>
 <aside class="product-card product-form"><div class="panel-title">Open ETH perpetual</div><form id="perp-form"><label>Direction<select id="perp-side"><option value="long">Long · price goes up</option><option value="short">Short · price goes down</option></select></label>${field('Margin','perp-margin',100,'USDC')}<label>Leverage<select id="perp-leverage"><option value="1">1×</option><option value="2">2×</option><option value="3" selected>3×</option><option value="5">5×</option><option value="10">10×</option></select></label><div id="perp-preview"></div><button class="primary" type="submit">Open demo position →</button><p id="perp-error" class="form-error" role="alert"></p></form><p class="fineprint">0.1% entry and exit fees. Maintenance margin is 5% of current notional. A liquidated position forfeits its remaining isolated margin. No expiry; close whenever you choose.</p></aside></div>
</section>
<section id="lending-page" hidden>
 <div class="product-heading"><div><span class="eyebrow">02 / CREDIT-BASED LENDING</span><h2>Your history opens doors.</h2><p>Explore undercollateralized borrowing with transparent, history-based demo terms.</p></div><span class="demo-pill">SYNTHETIC CREDIT PROFILE</span></div>
 <div class="product-grid"><div class="product-main"><div class="metric-row" id="credit-metrics"></div><div class="product-card"><div class="panel-title">What shapes your credit <span>Inspectable scoring</span></div><div id="credit-breakdown"></div><p class="fineprint">Synthetic starting score: 560. Settled spot trades add 5 points each (max 60); on-time loans held at least 7 simulated days add 30 each (max 150); each overdue loan subtracts 100. Score is clamped to 300–850. This is an illustrative rule, not a real credit assessment or Sybil-resistant system.</p></div>
 <div class="product-card"><div class="panel-title">Active loan <span id="day-label"></span></div><div id="active-loan"></div></div><div class="product-card scenario"><div class="panel-title">Explore interest over time</div><p>Only these controls advance loan time. Simple interest accrues daily; payment is due in 30 simulated days.</p><div class="scenario-buttons"><button data-days="1">+1 day</button><button data-days="7">+7 days</button><button data-days="30">+30 days</button></div></div></div>
 <aside class="product-card product-form"><div class="panel-title">Borrow USDC</div><form id="loan-form">${field('Loan amount','loan-amount',250,'USDC')}<div id="loan-preview"></div><button class="primary" type="submit">Borrow demo USDC →</button><p id="loan-error" class="form-error" role="alert"></p></form><p class="fineprint">One active loan at a time. Collateral is locked in USDC and is lower than the loan principal. Repayment automatically applies released collateral. Overdue debt remains payable and lowers your score. The demo lending reserve is simulated.</p></aside></div>
</section>
<section id="liquidity-page" hidden>
 <div class="product-heading"><div><span class="eyebrow">03 / ADAPTIVE MARKET MAKING</span><h2>Put liquidity to work.</h2><p>A constant-product ETH / USDC vault that reprices as simulated trades change its inventory.</p></div><span class="demo-pill">DEMO LIQUIDITY VAULT</span></div>
 <div class="product-grid"><div class="product-main"><div class="metric-row" id="maker-metrics"></div><div class="product-card"><div class="panel-title">Inventory & executable quotes <span>ETH / USDC</span></div><div id="maker-inventory"></div></div><div class="product-card scenario"><div class="panel-title">Simulate external order flow</div><p>Sample counterparties trade against your pool. Reserves, quotes, inventory weights, and fees update together.</p>${field('External trade notional','flow-amount',50,'USDC')}<div class="scenario-buttons"><button id="flow-buy">Trader buys ETH ↗</button><button id="flow-sell">Trader sells ETH ↘</button></div><p class="fineprint">Sample counterparties use separate simulated funds, not your wallet. Flow is capped at 20% of vault value per trade. Displayed quotes are marginal prices; actual fills include price impact.</p><p id="maker-error" class="form-error" role="alert"></p></div></div>
 <aside class="product-card product-form"><div class="panel-title">Provide liquidity</div><form id="maker-form">${field('USDC side of deposit','maker-amount',500,'USDC')}<div id="maker-preview"></div><button class="primary" type="submit">Deposit paired assets →</button><p id="deposit-error" class="form-error" role="alert"></p></form><button id="withdraw-vault" class="subtle wide">Withdraw full vault</button><p class="fineprint">Deposit equal-value ETH and USDC at the current simulated mark. Swaps follow x · y = k with fees retained in reserves. Fees widen with inventory imbalance (0.3%–1.5%). Pool value may differ from holding the deposited assets.</p></aside></div>
</section>
<section id="protocol-log" hidden class="product-card"><div class="panel-title">Protocol activity <span>Local simulation records · not blockchain receipts</span></div><div id="protocol-events"></div></section>`;
$('.bottom-note').before(shells);
function metric(label,value,note){return `<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;}
function line(k,v){return `<div class="cost"><span>${k}</span><strong>${v}</strong></div>`;}
function action(errorId,fn,message){$('#'+errorId).textContent='';try{fn();save();refresh();if(message)toast(message)}catch(e){$('#'+errorId).textContent=e.message;}}
function positionPreview(){const p=E.init(state),margin=Number($('#perp-margin').value),lev=Number($('#perp-leverage').value),side=$('#perp-side').value;const n=margin*lev;const liq=margin>0?E.liquidation({qty:n/p.mark,margin,entry:p.mark,side}):0;$('#perp-preview').innerHTML=line('Available USDC',fmt(state.connected?state.balances.USDC:0))+line('Position notional',fmt(n)+' USDC')+line('Entry fee',fmt(n*.001)+' USDC')+line('Estimated liquidation',liq>0?'$'+fmt(liq):'No positive-price threshold');}
function loanPreview(){const t=E.terms(state),n=Number($('#loan-amount').value);$('#loan-preview').innerHTML=line('Available USDC',fmt(state.connected?state.balances.USDC:0))+line('Collateral required',fmt(n*t.collateral)+' USDC')+line('Fixed APR',fmt(t.apr*100)+'%')+line('30-day repayment',fmt(n*(1+t.apr*30/365))+' USDC');}
function makerPreview(){const n=Number($('#maker-amount').value),p=E.init(state);$('#maker-preview').innerHTML=line('Paired ETH required',fmt(n/p.mark,6)+' ETH')+line('Total deposit value',fmt(n*2)+' USDC')+line('Available ETH',fmt(state.connected?state.balances.ETH:0,6))+line('Available USDC',fmt(state.connected?state.balances.USDC:0));}
function refreshProducts(){const p=E.init(state),t=E.terms(state),q=E.quote(state);$('#perp-metrics').innerHTML=metric('ETH mark price','$'+fmt(p.mark),'Synthetic execution price')+metric('Index price','$'+fmt(p.index),'Scenario reference')+metric('Funding / block',fmt(p.funding*100,5)+'%',p.funding>=0?'Longs pay shorts':'Shorts pay longs');$('#block-label').textContent='Block '+p.block;
 $('#positions').innerHTML=p.positions.length?table(['Position','Margin / equity','PnL¹','Liquidation²',''],p.positions.map(x=>{const pnl=E.equity(x,p.mark)-x.initial,liq=E.liquidation(x);return `<tr><td>ETH ${x.side} · ${x.leverage}×<small>${fmt(x.qty,5)} ETH @ ${fmt(x.entry)}</small></td><td>${fmt(x.margin)} / ${fmt(E.equity(x,p.mark))}</td><td class="${pnl>=0?'green':'loss'}">${fmt(pnl)}<small>Funding paid: ${fmt(x.funding,4)}</small></td><td>${liq>0?fmt(liq):'—'}</td><td><button data-close-position="${x.id}">Close</button></td></tr>`}))+ '<p class="fineprint">¹ Includes funding, excludes entry/exit fees. ² Recalculated after funding; scenario steps may gap through the threshold.</p>':'<div class="empty">No open positions.<p>Choose a direction and margin to test a market view.</p></div>';
 $('#closed-positions').innerHTML=p.closed.length?table(['Direction','Entry → exit','Realized PnL','Status'],p.closed.map(x=>`<tr><td>${x.side} · ${x.leverage}×</td><td>${fmt(x.entry)} → ${fmt(x.exit)}</td><td class="${x.pnl>=0?'green':'loss'}">${fmt(x.pnl)} USDC</td><td>${x.status}</td></tr>`)):'<div class="empty">Closed and liquidated positions will appear here.</div>';
 $('#credit-metrics').innerHTML=metric('Demo credit score',t.score,'Range 300–850')+metric('Borrowing limit',fmt(t.limit)+' USDC','Based on synthetic history')+metric('Collateral ratio',fmt(t.collateral*100,0)+'%',fmt(t.apr*100,0)+'% APR · 30-day term');$('#credit-breakdown').innerHTML=line('Settled spot trades',state.history.length)+line('Qualifying repayments',p.repaid)+line('Overdue loans',p.defaults)+`<div class="score-track"><span style="width:${(t.score-300)/550*100}%"></span></div>`;$('#day-label').textContent='Simulation day '+p.day;
 $('#active-loan').innerHTML=p.loans.length?p.loans.map(l=>line('Principal',fmt(l.principal)+' USDC')+line('Locked collateral',fmt(l.collateral)+' USDC')+line('Accrued interest',fmt(E.debt(p,l)-l.principal,4)+' USDC')+line('Total debt',fmt(E.debt(p,l),4)+' USDC')+line('Due',`Day ${l.due} · ${l.late?'Overdue':Math.max(0,l.due-p.day)+' days left'}`)+`<button class="subtle" data-repay="${l.id}">Repay full loan →</button>`).join(''):'<div class="empty">No outstanding loans.<p>Your next terms are determined by the profile above.</p></div>';
 $('#maker-metrics').innerHTML=metric('Vault value',q?'$'+fmt(q.value):'$0.00','Marked at synthetic ETH price')+metric('Retained fee value',p.pool?fmt(p.pool.fees)+' USDC':'0.00 USDC','Notional at fill · included in reserves')+metric('Adaptive swap fee',q?fmt(q.fee*100,3)+'%':'0.300%','Wider when inventory is imbalanced');$('#maker-inventory').innerHTML=q?line('Pool reserves',fmt(p.pool.eth,6)+' ETH / '+fmt(p.pool.usd)+' USDC')+line('ETH weight',fmt(q.weight*100,1)+'%')+`<div class="score-track"><span style="width:${q.weight*100}%"></span></div><div class="quote-cards"><div>Bid / pool buys ETH<strong>${fmt(q.bid)}</strong></div><div>Ask / pool sells ETH<strong>${fmt(q.ask)}</strong></div></div>`+line('Sample fills',p.pool.fills)+line('Value vs. holding deposits',fmt(q.value-q.hold)+' USDC'):'<div class="empty">Your vault is ready to be funded.<p>Deposit paired assets to activate two-sided quotes.</p></div>';
 $('#withdraw-vault').disabled=!p.pool;$('#protocol-events').innerHTML=p.events.length?p.events.slice(0,8).map(e=>`<div class="event-row"><span>Block ${e.block} · day ${e.day}</span><p>${e.text}</p></div>`).join(''):'<div class="empty">Your protocol actions will appear here.</div>';$('#protocol-log').hidden=!productPages.some(([id])=>!$('#'+id+'-page').hidden);positionPreview();loanPreview();makerPreview();$$('[data-close-position]').forEach(b=>b.onclick=()=>action('perp-error',()=>E.close(state,b.dataset.closePosition),'Position closed.'));$$('[data-repay]').forEach(b=>b.onclick=()=>action('loan-error',()=>E.repay(state,b.dataset.repay),'Loan repaid.'));
}
$('#perp-form').onsubmit=e=>{e.preventDefault();action('perp-error',()=>E.open(state,Number($('#perp-margin').value),Number($('#perp-leverage').value),$('#perp-side').value),'Demo position opened.')};$('#loan-form').onsubmit=e=>{e.preventDefault();action('loan-error',()=>E.borrow(state,Number($('#loan-amount').value)),'Demo loan funded.')};$('#maker-form').onsubmit=e=>{e.preventDefault();action('deposit-error',()=>E.deposit(state,Number($('#maker-amount').value)),'Maker vault funded.')};$$('[data-move]').forEach(b=>b.onclick=()=>action('perp-error',()=>E.block(state,Number(b.dataset.move))));$$('[data-days]').forEach(b=>b.onclick=()=>action('loan-error',()=>E.days(state,Number(b.dataset.days))));$('#withdraw-vault').onclick=()=>action('deposit-error',()=>E.withdraw(state),'Vault assets returned.');$('#flow-buy').onclick=()=>action('maker-error',()=>E.fill(state,'buy',Number($('#flow-amount').value)));$('#flow-sell').onclick=()=>action('maker-error',()=>E.fill(state,'sell',Number($('#flow-amount').value)));['perp-margin','perp-leverage','perp-side'].forEach(id=>$('#'+id).oninput=positionPreview);$('#loan-amount').oninput=loanPreview;$('#maker-amount').oninput=makerPreview;
$$('[data-page]').forEach(b=>b.onclick=()=>{navigate(b.dataset.page);refreshProducts()});
$('.steps').insertAdjacentHTML('beforeend','<div><b>04 · Explore more markets</b><p>Perpetuals model isolated margin, block funding, and liquidations. Lending models synthetic credit terms and daily interest. Market making models a constant-product pool with inventory-sensitive fees. All mechanisms run locally; none are smart contracts.</p></div>');
refreshProducts();
